int main(void)
{
    int score;
    char grade = 'E';

    if (scanf("%d", &score) != 1)
        return 0;

    switch (score / 10) {
    case 10:
    case 9:
        grade = 'A';
        break;
    case 8:
        grade = 'B';
        break;
    case 7:
        grade = 'C';
        break;
    case 6:
        grade = 'D';
        break;
    default:
        grade = 'E';
        break;
    }

    printf("%c\n", grade);
    return 0;
}

