#include <stdio.h>

int main(void)
{
    long long n;
    int digits = 0;
    int sum = 0;

    if (scanf("%lld", &n) != 1 || n < 0)
        return 0;

    do {
        sum += (int)(n % 10);
        n /= 10;
        digits++;
    } while (n > 0);

    printf("%d %d\n", digits, sum);
    return 0;
}

