int main(void)
{
    int n, i, k, dist, stars;

    if (scanf("%d", &n) != 1 || n < 1)
        return 0;

    for (i = 0; i < 2 * n - 1; i++) {
        dist = (i < n - 1) ? (n - 1 - i) : (i - (n - 1));
        stars = 2 * (n - dist) - 1;
        for (k = 0; k < dist; k++)
            putchar(' ');
        for (k = 0; k < stars; k++)
            putchar('*');
        putchar('\n');
    }

    return 0;
}

