        for (i = 2; i * i <= p; i++) {
            if (p % i == 0) {
                p_prime = 0;
                break;
            }
        }

        q = n - p;
        for (i = 2; i * i <= q; i++) {
            if (q % i == 0) {
                q_prime = 0;
                break;
            }
        }

        if (p_prime && q_prime) {
            printf("%d = %d + %d\n", n, p, q);
            found = 1;
            break;
        }
    }

    if (!found)
        printf("none\n");

    return 0;
}

